import{_ as o,o as a,c as r,a2 as c}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"Ring 3：系统调用、ELF 加载与进程","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/syscall-ring3.md","filePath":"zh/arch/syscall-ring3.md"}'),d={name:"zh/arch/syscall-ring3.md"};function l(t,e,s,n,i,h){return a(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="ring-3-系统调用、elf-加载与进程" tabindex="-1">Ring 3：系统调用、ELF 加载与进程 <a class="header-anchor" href="#ring-3-系统调用、elf-加载与进程" aria-label="Permalink to &quot;Ring 3：系统调用、ELF 加载与进程&quot;">​</a></h1><h2 id="系统调用-abi" tabindex="-1">系统调用 ABI <a class="header-anchor" href="#系统调用-abi" aria-label="Permalink to &quot;系统调用 ABI&quot;">​</a></h2><p><code>kernel/core/core_syscall.h</code>：<code>rax</code> = 系统调用号，<code>rdi</code>/<code>rsi</code>/ <code>rdx</code>/<code>r10</code> = 参数，<code>rax</code> = 返回值（&gt;= 0 成功，&lt; 0 错误）。 定义了 53 个系统调用号（验证： <code>grep -c &#39;#define SYS_&#39; kernel/core/core_syscall.h</code>）。</p><h2 id="用户程序" tabindex="-1">用户程序 <a class="header-anchor" href="#用户程序" aria-label="Permalink to &quot;用户程序&quot;">​</a></h2><p><code>kernel/core/core_usermode.c</code> + 汇编跳板：ring-3 入口， fork (<code>arch_enter_ring3_fork.S</code>)、ELF 加载器、进程表、 信号。<code>userprogs/</code> 提供测试程序集 - hello、fork、exec、pipe、 signal、select、mmap 变体，以及动态链接系列。</p><h2 id="动态链接-一个真正的树内-ld-so" tabindex="-1">动态链接 - 一个真正的树内 ld.so <a class="header-anchor" href="#动态链接-一个真正的树内-ld-so" aria-label="Permalink to &quot;动态链接 - 一个真正的树内 ld.so&quot;">​</a></h2><p><code>libs/ld_so.c</code> 是一个共享对象加载器：<code>run so_test</code>、<code>run dlsym_test</code>、<code>run pie_test</code>、<code>run reloc_test</code>、<code>run dyn_hello</code>、 <code>run g7mmap</code> 都在使用它。L1 模块以相同方式在运行时加载 - 见 <a href="./../l1/solib-loader.html">../l1/solib-loader.md</a>。</p><h2 id="用户程序如何运行" tabindex="-1">用户程序如何运行 <a class="header-anchor" href="#用户程序如何运行" aria-label="Permalink to &quot;用户程序如何运行&quot;">​</a></h2><p><code>run &lt;name&gt;</code> 查找嵌入式程序头（通过 <code>tools/embed_userprog.py</code> / <code>tools/build_c_userprog.py</code> 在内核构建时从 <code>userprogs/</code> 构建） 或挂载文件系统上的文件，加载 ELF，并进入 ring 3。程序通过系统调用进行 I/O； 当它退出时，其槽位返回到进程表。</p><h2 id="来自-ring-3-的故障" tabindex="-1">来自 Ring 3 的故障 <a class="header-anchor" href="#来自-ring-3-的故障" aria-label="Permalink to &quot;来自 Ring 3 的故障&quot;">​</a></h2><p>用户模式的 #PF 如果不是增长则会升级为按进程终止（不是内核崩溃）； 用户模式的 #DE/#UD 同样如此。E2E 套件覆盖了所有这些内容 （<code>int3_user</code> 从 shell 作为测试运行）。</p>',11)])])}const u=o(d,[["render",l]]);export{p as __pageData,u as default};
